function toast(t,type="success"){const e=$("#toast");e.textContent=(type==="error"?"! ":"✓ ")+t;e.className="toast "+type+" show";clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove("show"),2400)}
// 所有 HTTP 请求从此处进入，方便嵌入式团队统一增加鉴权、超时或错误码转换。
async function api(url,opt){if(SIM)throw Error("simulation");const r=await fetch(url,Object.assign({cache:"no-store"},opt||{}));let data={};try{data=await r.json()}catch(e){}if(!r.ok||data.ok===false){const error=new Error(data.message||("HTTP "+r.status));error.status=r.status;error.code=data.code||"HTTP_ERROR";error.data=data.data;throw error}return data}
// 真机写入失败时绝不更新本地状态；仅 file/localhost 预览允许模拟成功。
async function mutate(url,opt){try{return await api(url,opt)}catch(error){if(DEMO)return{ok:true,demo:true};throw error}}
function showPage(page){state.page=page;$$('[id^="page-"]').forEach(e=>e.classList.toggle("active",e.id==="page-"+page));$$('.side nav button').forEach(b=>b.classList.toggle("active",b.dataset.page===page));$("#side").classList.remove("open");$("#shade").classList.remove("show");if(page==="zones")zoneHome();if(page==="wifi")scanWifi();if(page==="ota")loadOta();if(page==="logs")startLogPoll();else stopLogPoll()}
function formatBytes(n){n=Number(n)||0;if(n<1024)return n+" B";if(n<1048576)return(n/1024).toFixed(1)+" KB";return(n/1048576).toFixed(2)+" MB"}
function stopLogPoll(){if(state.logTimer){clearInterval(state.logTimer);state.logTimer=null}}
function startLogPoll(){stopLogPoll();state.logPaused=false;const btn=$("#pauseLogs");if(btn)btn.textContent=state.lang==="en"?"Pause":"暂停";refreshLogs(true);state.logTimer=setInterval(()=>{if(state.page==="logs"&&!state.logPaused&&!state.otaBusy)refreshLogs(false)},1000)}
function appendLogLines(lines,reset){const view=$("#logView");if(!view)return;if(reset)view.textContent="";if(!lines||!lines.length){if(reset||!view.textContent.trim())view.textContent=state.lang==="en"?"No logs yet.":"暂无日志";return}const chunk=lines.map(l=>l.text||"").filter(Boolean).join("\n");if(reset)view.textContent=chunk;else{if(view.textContent&&!view.textContent.endsWith("\n"))view.textContent+="\n";view.textContent+=chunk}if($("#logFollow")?.checked)view.scrollTop=view.scrollHeight}
async function refreshLogs(full){const filter=($("#logFilter")?.value||"").trim(),meta=$("#logMeta");try{const q=new URLSearchParams;if(filter)q.set("tag",filter);q.set("limit",full?"150":"80");if(!full&&state.logSeq)q.set("since",String(state.logSeq));const d=await api("/api/logs?"+q.toString());const lines=d.lines||[];if(full||!state.logSeq)appendLogLines(lines,true);else if(lines.length)appendLogLines(lines,false);state.logSeq=d.seq||state.logSeq||0;if(meta)meta.textContent=(state.lang==="en"?"seq ":"序号 ")+state.logSeq+" · "+(lines.length?(full?lines.length+" lines":"+"+lines.length): (state.lang==="en"?"idle":"无新增"))}catch(e){if(DEMO){appendLogLines([{text:"I (1234) c4004: people_count tag[0] motion=1 static=0"},{text:"I (1250) c4004: boundary tag[1] enterExit=0x01 enter=1 exit=0"}],true);if(meta)meta.textContent="demo";return}if(meta)meta.textContent=e.message||"error"}}
async function clearLogs(){if(!await confirmAction(state.lang==="en"?"Clear the device log buffer?":"确定清空设备端日志缓冲吗？"))return;try{await mutate("/api/logs",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"clear"})});state.logSeq=0;appendLogLines([],true);toast(state.lang==="en"?"Logs cleared":"日志已清空")}catch(e){toast(e.message||"清空失败","error")}}
function toggleLogPause(){state.logPaused=!state.logPaused;$("#pauseLogs").textContent=state.logPaused?(state.lang==="en"?"Resume":"继续"):(state.lang==="en"?"Pause":"暂停")}
function setOtaProgress(done,total){const pct=total?Math.min(100,Math.round(done/total*100)):0;$("#otaBar").style.width=pct+"%";$("#otaPercent").textContent=pct+"%";$("#otaBytes").textContent=formatBytes(done)+" / "+formatBytes(total)}
function setFwMeta(version){const v=version||"—";$("#fwMeta").textContent=(state.lang==="en"?"Firmware: ":"固件：")+v;$("#otaVersion").textContent=v}
async function loadOta(){const badge=$("#otaState"),msg=$("#otaMessage");try{const d=await api("/api/ota");setFwMeta(d.version);$("#otaPartition").textContent=(state.lang==="en"?"Partition: ":"分区：")+(d.running||"—");if($("#otaStorage"))$("#otaStorage").textContent=(state.lang==="en"?"Web partition: ":"网页分区：")+formatBytes(d.storage_size||0);badge.textContent=d.pending_verify?(state.lang==="en"?"Pending Verify":"待验证"):(state.lang==="en"?"Running":"运行正常");badge.className="badge"+(d.pending_verify?"":" ok");if(!state.otaBusy)msg.className="message"}catch(e){if(DEMO){setFwMeta("1.1.1-demo");$("#otaPartition").textContent=state.lang==="en"?"Partition: ota_0":"分区：ota_0";if($("#otaStorage"))$("#otaStorage").textContent=(state.lang==="en"?"Web partition: ":"网页分区：")+"1.0 MB";badge.textContent=state.lang==="en"?"Running":"运行正常";badge.className="badge ok";return}badge.textContent=state.lang==="en"?"Unavailable":"不可用";badge.className="badge";msg.className="message err";msg.textContent=e.message||"无法读取固件信息"}}
function otaFileLabel(inputId,nameId,emptyText){const file=$(inputId).files?.[0],name=$(nameId);if(!file){name.textContent=emptyText;return null}const ok=/\.bin$/i.test(file.name)||file.type==="application/octet-stream";name.textContent=ok?file.name+" ("+formatBytes(file.size)+")":file.name+" — invalid";return ok?file:null}
function onOtaFileChange(){const app=otaFileLabel("#otaFile","#otaFileName",state.lang==="en"?"Not selected":"未选择"),ui=otaFileLabel("#otaUiFile","#otaUiFileName",state.lang==="en"?"Not selected (optional)":"未选择（可选）"),btn=$("#startOta"),msg=$("#otaMessage"),total=(app?app.size:0)+(ui?ui.size:0);btn.disabled=(!app&&!ui)||state.otaBusy;setOtaProgress(0,total);msg.className="message";msg.textContent=(!app&&!ui)?(state.lang==="en"?"Select firmware and/or storage.bin":"至少选择固件或网页镜像之一。改页面必须上传 storage.bin。"):(state.lang==="en"?"Ready to upload.":"已选择文件，可开始升级。")}
function uploadOta(file,target,reboot){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest(),q="target="+encodeURIComponent(target)+"&reboot="+(reboot?"1":"0");xhr.open("POST","/api/ota?"+q);xhr.responseType="json";xhr.upload.onprogress=e=>{if(!e.lengthComputable)return;const base=state.otaProgressBase||0;setOtaProgress(base+e.loaded,(state.otaProgressTotal||e.total))};xhr.onload=()=>{let data=xhr.response;if(!data||typeof data!=="object"){try{data=JSON.parse(xhr.responseText||"{}")}catch(err){data={}}}if(xhr.status>=200&&xhr.status<300&&data.ok!==false)resolve(data);else reject(new Error(data.message||("HTTP "+xhr.status)))};xhr.onerror=()=>reject(new Error("network error"));xhr.onabort=()=>reject(new Error("aborted"));xhr.send(file)})}
