function boxFromCoords(coords){if(!Array.isArray(coords)||coords.length<2)return null;const r=radarRange(),xs=coords.map(c=>Number(c[0])),ys=coords.map(c=>Number(c[1])),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);return{left:(minX-r.xmin)/r.w*100,top:(minY-r.ymin)/r.h*100,width:(maxX-minX)/r.w*100,height:(maxY-minY)/r.h*100}}
