// 区域越界或检测范围与已有区域冲突时，禁止保存并展示可执行的处理入口。
function validateDraft(type){if(type==="region"){const complete=state.regionPoints.length===4,outer=state.returnToCalibration&&state.points.length===4?state.points:state.boundary,outside=complete?outsidePointIndexes(state.regionPoints,outer):[],valid=complete&&!outside.length,saveButton=$("#saveRegion");saveButton.disabled=!valid;const panel=$("#regionValidation");panel.className="validation-panel "+(valid?"valid":outside.length?"error":"");panel.innerHTML=valid?"<b>✓ 区域范围有效</b>":outside.length?`<b>! 区域超出检测范围</b><span>点 ${outside.map(i=>i+1).join("、")} 越界。请调整标红的角点，区域必须完整位于检测范围内。</span>`:"<span>完成四个点采集后将自动校验区域范围。</span>"}
else{const complete=state.points.length===4,conflicts=complete?conflictingRegions():[],saveButton=$("#saveRange");saveButton.disabled=!complete||conflicts.length>0;renderConflictPanel(conflicts)}}
function renderConflictPanel(conflicts){const panel=$("#rangeValidation");panel.className="validation-panel "+(conflicts.length?"error":"valid");panel.innerHTML=conflicts.length?`<b>! 检测范围与已有区域冲突（${conflicts.length}）</b><span>请先调整、裁剪或删除冲突区域，再保存检测范围。</span><div class="conflict-list">${conflicts.map(r=>{const canClip=!!intersectRect(r.coords,draftBoundary());return `<div><strong>${escapeHtml(r.name)}</strong><em>冲突</em><button data-conflict-action="adjust" data-id="${Number(r.id)}">调整区域</button><button data-conflict-action="clip" data-id="${Number(r.id)}" ${canClip?"":"disabled"}>${canClip?"裁剪到范围内":"无法裁剪"}</button><button data-conflict-action="delete" data-id="${Number(r.id)}">删除</button></div>`}).join("")}</div>`:"<b>✓ 检测范围与全部区域兼容</b>";panel.querySelectorAll("[data-conflict-action]").forEach(button=>button.onclick=()=>resolveConflict(button.dataset.conflictAction,Number(button.dataset.id)))}
async function resolveConflict(action,id){const region=state.regions.find(r=>r.id===id);if(!region)return;if(action==="adjust"){state.returnToCalibration=true;openRegionEditor(id);return}if(action==="delete"){if(!await confirmAction("确定删除冲突区域："+region.name+"？"))return;try{await mutate("/api/config",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"delete_tag",id})})}catch(error){return toast(error.message||"区域删除失败","error")}state.regions=state.regions.filter(r=>r.id!==id);renderPoints("range");return}const clipped=intersectRect(region.coords,draftBoundary());if(!clipped)return toast("该区域完全位于检测范围外，无法裁剪，请调整或删除","error");if(!await confirmAction("将“"+region.name+"”裁剪到新的检测范围内？"))return;const updated=Object.assign({},region,{coords:clipped});try{await mutate("/api/config",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"update_tag",id:updated.id,name:updated.name,strategy:updated.strategy,setting:updated.setting||null,coords:updated.coords})})}catch(error){return toast(error.message||"区域裁剪失败","error")}state.regions[state.regions.findIndex(r=>r.id===id)]=updated;renderPoints("range");toast("区域已裁剪")}
function updateCoord(){$("#liveX").textContent=state.x.toFixed(1);$("#liveY").textContent=state.y.toFixed(1);$$('.mirrorX').forEach(e=>e.textContent=state.x.toFixed(1));$$('.mirrorY').forEach(e=>e.textContent=state.y.toFixed(1));}
function radarRange(){const r=state.radarFov||{x_min:-2,x_max:2,y_min:0,y_max:7};const xmin=Number(r.x_min),xmax=Number(r.x_max),ymin=Number(r.y_min),ymax=Number(r.y_max);return{xmin,xmax,ymin,ymax,w:Math.max(0.1,xmax-xmin),h:Math.max(0.1,ymax-ymin)}}
/** 侧装：雷达在地图上部中央；X 左右对称，Y+ 向前（地图向下）。全宽地图内按 FOV 比例投影。 */
function radarToPercent(x,y){const r=radarRange();let left=(Number(x)-r.xmin)/r.w*100,top=(Number(y)-r.ymin)/r.h*100;left=Math.max(2,Math.min(98,left));top=Math.max(2,Math.min(98,top));return{left,top}}
