// 每秒刷新一次实时数据；环境数据、人体坐标和统计值允许后端按需缺省。
async function refresh(){try{const d=await api("/api/data");showDataState(false);updateHealth(d);if(d.env_ready!==false){$("#temp").textContent=Number(d.temp??26.3).toFixed(1)+"°C";$("#humidity").textContent=Number(d.humidity??58).toFixed(1)+" %RH";$("#co2").textContent=`${d.co2??645} ppm`;$("#light").textContent=String(Math.round(Number(d.light??215)))+" lux";$("#sound").textContent=(d.sound==null?"—":String(Math.round(Number(d.sound))))+" dB";const event=typeof d.sound_event==="string"?d.sound_event:d.sound_event?.type;$("#soundEvent").textContent=event||(state.lang==="en"?"No Abnormal Event":"无异常事件");$("#soundEventTime").textContent=d.sound_event?.time||(state.lang==="en"?"Last 24 Hours":"最近24小时")}if(d.mmwave?.fov)syncFov(d.mmwave.fov);const targets=d.mmwave?.targets||[];renderLiveTargets(targets);const picked=targets.find(t=>t.picked)||targets[0];if(picked&&picked.x!=null){state.x=Number(picked.x);state.y=Number(picked.y);updateCoord()}if(d.mmwave){$("#activePeople").textContent=(d.mmwave.active_count||0)+" 人";$("#staticPeople").textContent=(d.mmwave.static_count||0)+" 人";const latest=d.mmwave.last_event||d.areas?.find(a=>a.event);if(latest){$("#radarEvent").textContent=typeof latest==="string"?latest:`${latest.name||"区域事件"}：${latest.event||latest.type||"—"}`;$("#radarEventTime").textContent=latest.time||latest.event_time||"刚刚"}}else if(Array.isArray(d.areas)&&d.areas[0]){$("#activePeople").textContent=(d.areas[0].active||0)+" 人";$("#staticPeople").textContent=(d.areas[0].static||0)+" 人"}renderLiveMap()}catch(e){if(!DEMO){showDataState(true,"设备尚未联网或暂未收到传感器数据。");$("#updated").textContent="设备数据暂不可用";return}}$("#updated").textContent="更新于 "+new Date().toLocaleTimeString("zh-CN",{hour12:false})}
