async function saveRange(){const coords=state.points.map(p=>[p.x,p.y]);if(coords.length!==4)return toast("请先完成四个点采集","error");const conflicts=conflictingRegions();if(conflicts.length){renderPoints("range");return toast("仍有区域超出新的检测范围，请先处理冲突","error")}const body={action:"set_range",coords};try{await mutate("/api/config",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)})}catch(error){return toast(error.message||"检测范围保存失败","error")}state.boundary=coords;renderRegions();toast("检测范围已保存并同步到实时监测");zoneHome()}
