async function saveRegion(){const name=$("#regionName").value.trim();if(!name)return toast(state.lang==="en"?"Enter a region name":"请先填写区域名称");const outer=state.returnToCalibration&&state.points.length===4?state.points:state.boundary,coords=state.regionPoints.map(p=>[p.x,p.y]);if(coords.length!==4||!isRectInside(coords,outer)){renderPoints("region");return toast("区域必须完整位于检测范围内","error")}const strategy=Number($("#regionType").value),setting=$("#tagSetting")?.value||null,id=state.editingRegionId,body={action:id?"update_tag":"add_tag",id,name,strategy,setting,coords};let result;try{result=await mutate("/api/config",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)})}catch(error){return toast(error.message||"区域保存失败","error")}if(id){const i=state.regions.findIndex(r=>r.id===id);state.regions[i]={id,name,strategy,setting,coords}}else state.regions.push({id:result.id||result.tag?.id||Date.now(),name,strategy,setting,coords});state.editingRegionId=null;renderRegions();toast(state.lang==="en"?"Region saved and synced":"区域已保存并同步到实时监测");if(state.returnToCalibration){$("#regionEditor").classList.add("hidden");$("#calibrate").classList.remove("hidden");state.returnToCalibration=false;renderPoints("range")}else zoneHome()}
